{"results": [{"id": "hp_doc_f588e495393c51f6621324f8105f7250b669041ac7d406b21c027f9ef03fdb91", "title": "Wolf Laurel, North Carolina", "text": "Wolf Laurel, North Carolina, is an unincorporated, private gated community, located in Madison and Yancey Counties of Western North Carolina. The unincorporated community is located approximately 30 miles north of Asheville, North Carolina, 6 miles from interstate 26 and borders the Cherokee National Forest, Tennessee state line and Appalachian Trail. It is named after Wolf Laurel Branch, which flows into Puncheon Fork after leaving the community upstream.", "score": 31.5897}, {"id": "hp_doc_94b02356d4de8938d3dc6b567c4e68f8c17e3ff6a22783a2e9fd8005f9b4e202", "title": "Pryor Mountains National Forest", "text": "Pryor Mountains National Forest was established as the Pryor Mountains Forest Reserve by the U.S. Forest Service in Montana on November 6, 1906 by the U.S. Forest Service with 78732 acre . It became a National Forest on March 4, 1907. On July 1, 1908 it was combined with part of Yellowstone National Forest to establish Beartooth National Forest. The name was discontinued.", "score": 14.9803}, {"id": "hp_doc_cca4fa41fcd75e8dbc964f0dc55a63fb07f14e9379c6d5b339f4d2ddd7ac36a5", "title": "Cherokee National Forest", "text": "The Cherokee National Forest is a large National Forest created on June 14, 1920 and managed by the U.S. Forest Service and encompassing some 655598 acre .", "score": 14.6508}], "remaining_searches": 2}
